try{const cached=JSON.parse(localStorage.getItem('sahne-catalog-cache-v1')||'[]');if(Array.isArray(cached))for(const raw of cached){const s=tvmazeShow(raw);if(s&&!byId.has(s.id)){dynamicShows.set(s.id,s);byId.set(s.id,s)}}}catch{}
function rememberTvmazeShow(raw){const s=tvmazeShow(raw);if(!s)return null;const existing=byId.get(s.id);if(existing&&!dynamicShows.has(s.id))return existing;TasteEngine.invalidate();const merged=existing?{...existing,...s}:s;if(existing?.productionPlatforms?.length){for(const key of ['description','reason','label','mood','backdrop'])merged[key]=existing[key];if(!raw.voteCount&&!raw.ratingCount)merged.voteCount=existing.voteCount||0;}dynamicShows.set(merged.id,merged);byId.set(merged.id,merged);return merged;}
function tasteCatalog(){return [...SERIES,...dynamicShows.values()]}
function registerHomeShow(raw){const show=rememberTvmazeShow(raw);if(!show)return null;for(const key of ['premiered','weight','voteCount','type','language','status'])if(raw[key]!==undefined&&raw[key]!==null&&(!show[key]||show[key]===0))show[key]=raw[key];return show}
const homeRankings={popular:(HOME_SHELVES.popular||[]).map(registerHomeShow).filter(Boolean),newest:(HOME_SHELVES.newest||[]).map(registerHomeShow).filter(Boolean),rated:(HOME_SHELVES.rated||[]).map(registerHomeShow).filter(Boolean)};

