function newestCandidates(rows){const now=new Date().toISOString().slice(0,10),cutoff=new Date(Date.now()-730*864e5).toISOString().slice(0,10),eligible=rows.filter(raw=>raw&&raw.premiered&&raw.premiered<=now&&raw.premiered>=cutoff&&['Scripted','Animation'].includes(raw.type)&&raw.image&&(raw.image.medium||raw.image.original));return [...new Map(eligible.map(raw=>[Number(raw.id),raw])).values()].sort((a,b)=>String(b.premiered).localeCompare(String(a.premiered))||(Number(b.weight)||0)-(Number(a.weight)||0)||(Number(b.rating?.average)||0)-(Number(a.rating?.average)||0)).slice(0,12)}
function setNewestStatus(live,checkedAt=Date.now()){const node=$('#newest-status');if(!node)return;const date=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(checkedAt));node.textContent=live?`Son katalog kontrolü · ${date}.`:'Son prömiyer kayıtları TVmaze kataloğundan.'}
function rankingMetric(show,kind){if(kind==='newest'&&show.premiered){const d=new Date(show.premiered+'T12:00:00');return `<strong>${new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short'}).format(d)}</strong><small>PRÖMİYER</small>`}if(show.rating>0)return `<strong>${show.rating.toFixed(1)}</strong><small>/ 10</small>`;return kind==='popular'?'<strong>ÖNE ÇIKAN</strong>':'<strong>YENİ</strong>'}
function rankingCard(show,index,kind){const status=getStatus(show.id),image=externalUrl(show.image?.medium)||externalUrl(show.image?.original)||noPoster,genre=show.genres.slice(0,1).map(g=>names[g]||g).join(''),date=show.premiered?show.premiered.slice(0,4):show.year,meta=[date,genre].filter(Boolean).join(' · '),votes=show.voteCount?`${show.voteCount.toLocaleString('tr-TR')} oy`:'';return `<article class="ranking-card"><div class="ranking-poster-wrap"><button class="ranking-poster-link" data-detail="${show.id}" aria-label="${esc(show.name)} ayrıntılarını aç"><img src="${esc(image)}" alt="" loading="lazy" width="210" height="295"><span class="ranking-position">${String(index+1).padStart(2,'0')}</span><span class="ranking-metric">${rankingMetric(show,kind)}</span></button><button class="ranking-save" data-status-action="${show.id}" data-status-value="${status==='planned'?'remove':'planned'}" aria-label="${esc(show.name)} ${status==='planned'?'sonra izle listesinden çıkar':'sonra izle listeme ekle'}" aria-pressed="${status==='planned'}">${status==='planned'?'✓':'＋'}</button></div><div class="ranking-card-copy"><button class="ranking-card-title" data-detail="${show.id}">${esc(show.name)}</button><div class="ranking-card-meta"><span>${esc(meta||'TVmaze kataloğu')}</span>${votes?`<span aria-hidden="true">·</span><span class="ranking-votes">${esc(votes)}</span>`:''}</div><div class="ranking-card-tools"><button class="ranking-card-watch" data-detail="${show.id}" data-detail-tab="watch">Nerede izlenir?</button>${ratingButtons(show)}</div></div></article>`}
function renderHomeRankings(){const roots={popular:$('#popular-rankings'),newest:$('#newest-rankings'),rated:$('#rated-rankings')},offsets=Object.fromEntries(Object.entries(roots).map(([key,node])=>[key,node?.scrollLeft||0]));for(const [kind,node] of Object.entries(roots)){if(!node)continue;let list=[...homeRankings[kind]];if(kind==='rated')list.sort((a,b)=>(b.rating||0)-(a.rating||0)||(b.voteCount||0)-(a.voteCount||0));if(kind==='newest')list.sort((a,b)=>String(b.premiered||'').localeCompare(String(a.premiered||''))||(b.weight||0)-(a.weight||0));node.innerHTML=list.length?list.map((show,index)=>rankingCard(show,index,kind)).join(''):'<div class="ranking-empty">Bu sıralama şu anda yüklenemedi.</div>';node.scrollLeft=offsets[kind]}const stamp=$('#ranking-updated');if(stamp&&HOME_SHELVES.updatedAt)stamp.textContent=`Popülerlik ve puan sıralaması · ${fmtDate(CATALOG_BOOTSTRAP.checkedAt.slice(0,10))}`}
function applyNewestRows(rows,live=false,checkedAt=Date.now()){const selected=newestCandidates(rows);if(selected.length){homeRankings.newest=selected.map(registerHomeShow).filter(Boolean);renderHomeRankings()}setNewestStatus(live,checkedAt)}
async function refreshNewestShelf(){try{const cached=JSON.parse(localStorage.getItem(homeFeedCacheKey)||'null');if(cached&&Array.isArray(cached.rows)&&Date.now()-Number(cached.savedAt)<6*3600e3){applyNewestRows(cached.rows,true,cached.savedAt);return}const updatesResponse=await fetch('https://api.tvmaze.com/updates/shows?since=month',{headers:{Accept:'application/json'}});if(!updatesResponse.ok)throw new Error('TVmaze güncelleme listesi yanıt vermedi');const updates=await updatesResponse.json(),latestId=Math.max(Number(HOME_SHELVES.latestId)||0,...Object.keys(updates||{}).map(Number).filter(Number.isSafeInteger));if(!Number.isSafeInteger(latestId)||latestId<1)throw new Error('TVmaze son kayıt bilgisi bulunamadı');const firstPage=Math.floor(latestId/250),pages=await Promise.all([firstPage,firstPage+1].map(async page=>{const response=await fetch(`https://api.tvmaze.com/shows?page=${page}`,{headers:{Accept:'application/json'}});if(response.status===404)return [];if(!response.ok)throw new Error('TVmaze dizi kataloğu yanıt vermedi');const rows=await response.json();return Array.isArray(rows)?rows:[]})),rows=pages.flat(),selected=newestCandidates(rows);if(!selected.length)throw new Error('Yeni prömiyer bulunamadı');localStorage.setItem(homeFeedCacheKey,JSON.stringify({savedAt:Date.now(),rows:selected}));applyNewestRows(selected,true)}catch{setNewestStatus(false)}}
let searchMatches=[];const searchCache=new Map();let searchTimer=0,searchController=null,searchSequence=0;const detailRequests=new Map();
function saveDynamicCatalog(){try{const important=new Set([...Object.keys(saved).map(Number),...Object.keys(ratings).map(Number)]),recent=searchMatches.filter(s=>!important.has(s.id)).slice(-20),kept=[...dynamicShows.values()].filter(s=>important.has(s.id));localStorage.setItem('sahne-catalog-cache-v1',JSON.stringify([...new Map([...recent,...kept].map(s=>[s.id,s])).values()]))}catch{}}
const rawRatings=readState('sahne-guest-taste-v1',localStorage.getItem('sahne-last-account')?{}:readState('sahne-taste-v1',{}));let ratings=Object.fromEntries(Object.entries(rawRatings).filter(([id,v])=>/^\d+$/.test(id)&&Number(id)>0&&Object.hasOwn(TasteEngine.weights,v)));
let saved={};const old=readState('sahne-list-v1',{});for(const s of SERIES){if(standardLists.some(([k])=>old[s.id]===k))saved[s.id]={status:old[s.id]};}
const rawLibrary=readState('sahne-guest-library-v1',localStorage.getItem('sahne-last-account')?{}:readState('sahne-library-v2',{}));if(rawLibrary.entries&&typeof rawLibrary.entries==='object')for(const [id,e] of Object.entries(rawLibrary.entries)){const n=Number(id);if(Number.isSafeInteger(n)&&n>0&&e&&typeof e==='object'&&!Array.isArray(e))saved[n]={...saved[n],...e};}
let customLists=Array.isArray(rawLibrary.lists)?rawLibrary.lists.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string').slice(0,30):[];
if(!Array.isArray(rawLibrary.lists)&&Array.isArray(rawLibrary.customLists))customLists=rawLibrary.customLists;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function persist(){try{localStorage.setItem(window.SahneStorageKey?.('library')||'sahne-guest-library-v1',JSON.stringify({entries:saved,lists:customLists}));saveDynamicCatalog();window.dispatchEvent(new Event('sahne:library-change'));return true}catch{toast('Tarayıcı alanı dolu. Arşivini indirip bir kopyasını sakla.');return false}}
function saveRatings(){try{localStorage.setItem(window.SahneStorageKey?.('taste')||'sahne-guest-taste-v1',JSON.stringify(ratings));saveDynamicCatalog();window.dispatchEvent(new Event('sahne:library-change'));return true}catch{return false}}
function ensureEntry(id){return saved[id]||(saved[id]={status:'planned'})}
function getStatus(id){return saved[id]?.status}
function reactionLabel(v){return v==='love'?'Çok beğendin':'Beğendin'}
function ratingButtons(s){return `<div class="rating-controls" role="group" aria-label="${esc(s.name)} dizisini değerlendir">${ratingOptions.map(([v,icon,label])=>`<button class="rating-button ${ratings[s.id]===v?'selected':''}" data-rate="${s.id}" data-value="${v}" aria-label="${esc(s.name)}: ${label}" aria-pressed="${ratings[s.id]===v}" title="${label}; tekrar dokunarak geri al"><span class="rate-icon" aria-hidden="true">${icon}</span><span class="rate-label">${label}</span></button>`).join('')}</div>`}
function rate(id,v){if(!byId.has(id)||!Object.hasOwn(TasteEngine.weights,v))return;ratings[id]===v?delete ratings[id]:ratings[id]=v;saveRatings();renderAll();if(ratings[id]&&!byId.get(id).summary)hydrateTvmazeDetails(id);if($('#detail').open&&state.detailId===id){detailTab('overview')}toast(ratings[id]?byId.get(id).name+' için tercihin kaydedildi. Önerilerin güncellendi.':'Değerlendirmen geri alındı; önerilerin yeniden hesaplandı.');}
function showForCountry(s){return WATCH_DATA[String(s.id)]?.countries?.[state.country]}
function providerType(v){return ({subscription:'Abonelik',buy:'Satın al',rent:'Kirala',free:'Ücretsiz'})[v]||'Platformda görüntüle'}
function providerMark(name){return esc(name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}
function sourceDate(w){return w?.checkedAt?fmtDate(w.checkedAt):'Bilgi şu an doğrulanamadı'}
function inlineProviders(s){const c=showForCountry(s);if(!c?.offers?.length)return '';return `<span class="card-provider">${c.offers.slice(0,2).map(o=>esc(o.name)).join(' · ')}${c.offers.length>2?` +${c.offers.length-2}`:''}</span>`}
function recommendationCandidates(){return tasteCatalog().filter(s=>s.image&&(!s.type||['Scripted','Animation'].includes(s.type))&&s.genres?.length&&s.year&&s.year<=new Date().getFullYear()&&(!s.premiered||s.premiered<=localDate())&&s.status!=='In Development');}
function recommendationReason(s){const x=TasteEngine.explanation(s,tasteCatalog(),ratings,saved);if(x.kind==='editor')return 'Popüler ve güçlü puanlı hikâyelerden bir başlangıç.';if(x.kind==='avoid')return 'Beğenmediğin dizilerden farklı bir keşif.';if(x.kind==='explore')return 'Sevdiğin hikâyelerin yanında farklı bir seçenek.';const feature=x.themes?.[0]||names[x.genres.find(g=>g!=='Drama')||x.genres[0]]||'anlatı dünyası';return `${x.source} dizisini ${reactionLabel(x.reaction).toLocaleLowerCase('tr')}: ${feature.toLocaleLowerCase('tr')} ortak.`}
function eligible(){return tasteCatalog().filter(s=>(state.mood==='all'||s.mood===state.mood)&&(state.genre==='all'||s.genres.includes(state.genre))&&(!state.query||normal([s.name,s.description,s.reason,...s.genres.map(g=>esc(names[g]||g))].join(' ')).includes(normal(state.query)))&&(!$('#available-only')?.checked||!!showForCountry(s)?.offers?.length))}
function renderRecommendations(){const catalog=tasteCatalog(),pool=TasteEngine.recommend(recommendationCandidates(),catalog,ratings,saved,12),profile=TasteEngine.insights(catalog,ratings,saved);$('#taste-count').textContent=profile.count?`${profile.positive} olumlu · ${profile.negative} olumsuz tercih`:'Henüz bir tercih yok';$('#taste-info').textContent=profile.count?'Her tepkin yeni önerilere yansır. Değerlendirdiğin ve arşivindeki diziler tekrar önerilmez.':'Beğendim veya çok beğendim ile yakın hikâyeler bul; beğenmedim ile benzerlerini geriye it.';$('#recommendation-grid').innerHTML=pool.slice(0,6).map((s,i)=>`<article class="recommendation"><img src="${s.backdrop||s.image.original||s.image.medium}" alt="" loading="lazy"><div class="rec-content"><span class="rec-rank">${String(i+1).padStart(2,'0')}</span><span class="tiny-label">${profile.count?'SANA GÖRE':'KEŞFE BAŞLA'}</span><button class="card-title" data-detail="${s.id}">${esc(s.name)}</button><p class="rec-reason">${esc(recommendationReason(s))}</p><p class="card-meta">${s.year||'—'} · ${s.genres.slice(0,2).map(g=>esc(names[g]||g)).join(' / ')}</p>${ratingButtons(s)}</div></article>`).join('');$('#recommendation-empty').hidden=!!pool.length;$$('.taste-feedback').forEach(root=>{root.innerHTML='<div class="taste-feedback-copy"><span class="tiny-label">'+(profile.count?'TERCİHLERİNLE GÜNCELLENDİ':'KİŞİSEL KEŞİF')+'</span><strong>'+ (profile.count?'Sıradaki hikâyelerin.':'Bir tepki, yeni bir hikâye.')+'</strong><p>'+esc(profile.count?profile.count+' tercihin bu önerileri şekillendiriyor.':'Beğendikçe bu alan sana göre değişir.')+'</p><button class="text-button" data-catalog-shelf="personal">Tüm önerilerimi gör</button></div><div class="taste-feedback-posters">'+pool.slice(0,4).map(s=>'<button data-detail="'+s.id+'" title="'+esc(recommendationReason(s))+'"><img src="'+esc(s.image.medium||s.image.original)+'" alt="'+esc(s.name)+' afişi" loading="lazy"><span>'+esc(s.name)+'</span></button>').join('')+'</div>';});}
function card(s,library=false){const e=saved[s.id]||{};const avg=e.stars?`${'★'.repeat(Math.floor(e.stars))}${e.stars%1?'½':''} <span>${(e.stars*2).toFixed(1)} / 10</span>`:'';return `<article class="card"><div class="poster"><button class="poster-open" data-detail="${s.id}" aria-label="${esc(s.name)} ayrıntıları"><img src="${s.image.medium||s.image.original||noPoster}" alt="${esc(s.name)} afişi" loading="lazy" width="210" height="295"></button><button class="save ${e.status==='planned'?'saved':''}" data-status-action="${s.id}" data-status-value="${e.status==='planned'?'remove':'planned'}" aria-label="${esc(s.name)} ${e.status==='planned'?'listemden çıkar':'sonra izle listeme ekle'}" aria-pressed="${e.status==='planned'}">${e.status==='planned'?'✓':'＋'}</button>${e.favorite?'<span class="poster-badge">'+iconSvg.heartFill+' FAVORİ</span>':`<span class="poster-badge">${esc(s.label||'SAHNE SEÇKİSİ')}</span>`}</div><button class="card-title" data-detail="${s.id}">${esc(s.name)}</button><div class="card-meta">${s.year||'—'}<span>·</span>${s.genres.slice(0,2).map(g=>esc(names[g]||g)).join(' / ')||'Tür bilgisi yok'}<span>·</span>${s.runtime?`~${s.runtime} dk`:'Süre bilgisi yok'}</div>${inlineProviders(s)}<div class="catalog-meta-badge">${s.status?`<span class="${s.status==='Running'?'running':''}">${esc(({Running:'Devam ediyor',Ended:'Tamamlandı','To Be Determined':'Durumu bekleniyor','In Development':'Yapım aşamasında'})[s.status]||s.status)}</span>`:''}${s.rating?`<span>TVmaze ${Number(s.rating).toFixed(1)}</span>`:''}</div>${avg?`<div class="stars-preview">${avg} ${e.review?'<span>· günlükte not var</span>':''}</div>`:''}${ratingButtons(s)}${library?`<label class="sr-only" for="status-${s.id}">${esc(s.name)} izleme durumu</label><select id="status-${s.id}" data-set-status="${s.id}">${standardLists.map(([v,t])=>`<option value="${v}" ${e.status===v?'selected':''}>${t}</option>`).join('')}<option value="remove">Arşivden kaldır</option></select>`:''}</article>`}
function renderCatalog(){renderBrowseCatalog();}
function searchStatus(message,loading=false){const node=$('#search-status');node.textContent=message;node.hidden=!message;node.dataset.loading=String(loading)}
async function queryTvmaze(query,signal){const key=normal(query.trim());if(searchCache.has(key))return searchCache.get(key);const response=await fetch(`https://api.tvmaze.com/search/shows?q=${encodeURIComponent(query.trim())}`,{signal,headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`TVmaze yanıtı: ${response.status}`);const rows=await response.json();if(!Array.isArray(rows))throw new Error('TVmaze yanıtı okunamadı');const results=[...new Map(rows.map(row=>rememberTvmazeShow(row?.show)).filter(Boolean).map(show=>[show.id,show])).values()];searchCache.set(key,results);return results}
function queueCatalogSearch(){clearTimeout(searchTimer);searchController?.abort();const sequence=++searchSequence,q=state.query.trim();searchMatches=[];if(q){state.collection=null;state.mood='all';state.genre='all';state.catalogShelf='all';state.catalogType='all';syncBrowseControls();}if(q.length<2){searchStatus(q?'En az iki harf yaz; TVmaze kataloğunda aramayı başlatayım.':'');renderCatalog();return}searchStatus('TVmaze kataloğunda aranıyor…',true);renderCatalog();const key=normal(q);if(searchCache.has(key)){searchMatches=searchCache.get(key);searchStatus(searchMatches.length?`TVmaze’den en yakın ${searchMatches.length} başlık eşleşmesi bulundu.`:'TVmaze kataloğunda eşleşme bulunamadı.');renderCatalog();return}searchTimer=setTimeout(async()=>{const controller=new AbortController();searchController=controller;try{const results=await queryTvmaze(q,controller.signal);if(sequence!==searchSequence||normal(state.query.trim())!==key)return;searchMatches=results;searchStatus(results.length?`TVmaze’den en yakın ${results.length} başlık eşleşmesi · doğru yapımı yılına göre seç.`:'TVmaze kataloğunda eşleşme bulunamadı.');renderCatalog();renderRecommendations();saveDynamicCatalog()}catch(error){if(error.name==='AbortError'||sequence!==searchSequence)return;searchStatus('Geniş katalog şu an yanıt vermiyor. Seçkideki eşleşmeler gösteriliyor.');renderCatalog() }},600)}
const navigationKey='sahneNavigation';
let restoringNavigation=false,historyBackPending=false;
const validViews=['discover','catalog','collections','list','platforms','community'];
function navigationUrl(nav){const route=nav.detailId?'dizi/'+encodeURIComponent(nav.detailId):nav.view==='community'?'sahne/'+(nav.communityView||'forum')+(nav.communityId?'/'+encodeURIComponent(nav.communityId):''):nav.view==='platforms'&&nav.platform&&nav.platform!=='all'?'platform/'+encodeURIComponent(nav.platform):({discover:'kesfet',catalog:'sahne/katalog',collections:'sahne/koleksiyonlar',list:'sahne/arsiv',platforms:'sahne/platformlar'}[nav.view]||'kesfet');const url=new URL(location.href);url.hash=route;return url.href}
function initializeNavigation(){let nav=history.state?.[navigationKey];if(!nav){const hash=location.hash.slice(1),viewRoute={'kesfet':'discover','sahne/katalog':'catalog','sahne/koleksiyonlar':'collections','sahne/arsiv':'list','sahne/platformlar':'platforms'},communityMatch=hash.match(/^sahne\/(forum|profile|activity|topic)(?:\/([^/]+))?$/),detailMatch=hash.match(/^dizi\/(\d+)$/),platformMatch=hash.match(/^platform\/(apple|hbo|netflix|disney)$/);nav={view:communityMatch?'community':platformMatch?'platforms':viewRoute[hash]||'discover',communityView:communityMatch?.[1]||'forum',communityId:communityMatch?.[2]?decodeURIComponent(communityMatch[2]):null,platform:platformMatch?.[1]||'all',detailId:detailMatch?Number(detailMatch[1]):null,detailTab:'overview',scrollY:window.scrollY,depth:0}}if(!validViews.includes(nav.view))nav={view:'discover',platform:'all',detailId:null,detailTab:'overview',scrollY:0,depth:0};state.view=nav.view;state.communityView=nav.communityView||'forum';state.communityId=nav.communityId||null;state.platform=nav.platform||'all';history.replaceState({...history.state,[navigationKey]:nav},'',location.href);return nav}
async function resolveNavigationDetail(nav){const id=Number(nav.detailId);if(!Number.isSafeInteger(id)||id<1)return;try{if(!byId.has(id)){await loadCatalogIndex();const row=catalogById.get(id);if(row)materializeCatalogShow(row);else{const r=await fetch('https://api.tvmaze.com/shows/'+id);if(!r.ok)throw Error('Show not found');rememberTvmazeShow(await r.json());}}if(Number(history.state?.[navigationKey]?.detailId)===id&&byId.has(id))detail(id,nav.detailTab||'overview');}catch{if(Number(history.state?.[navigationKey]?.detailId)===id){toast('Bu dizi kaydına şu an ulaşılamadı. Katalogdan yeniden deneyebilirsin.');replaceNavigation({detailId:null});}}}
function pushNavigation(nav){const current=history.state?.[navigationKey];if(current)history.replaceState({...history.state,[navigationKey]:{...current,scrollY:window.scrollY}},'',location.href);const next={view:nav.view,communityView:nav.communityView||state.communityView||'forum',communityId:nav.communityId??state.communityId??null,platform:nav.platform||state.platform||'all',detailId:nav.detailId||null,detailTab:nav.detailTab||'overview',scrollY:window.scrollY,depth:(Number(current?.depth)||0)+1};history.pushState({...history.state,[navigationKey]:next},'',navigationUrl(next))}
function replaceNavigation(changes){const current=history.state?.[navigationKey];if(!current)return;const next={...current,...changes,scrollY:current.detailId?current.scrollY:window.scrollY};history.replaceState({...history.state,[navigationKey]:next},'',navigationUrl(next))}
function restoreNavigation(event){historyBackPending=false;const nav=event.state?.[navigationKey];if(!nav||!validViews.includes(nav.view)){if($('#detail').open){restoringNavigation=true;$('#detail').close();restoringNavigation=false}state.detailId=null;return}restoringNavigation=true;state.communityView=nav.communityView||'forum';state.communityId=nav.communityId||null;state.platform=nav.platform||'all';setView(nav.view,false,true);if(nav.detailId)resolveNavigationDetail(nav);else{state.detailId=null;if($('#detail').open)$('#detail').close()}requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo(0,Math.max(0,Number(nav.scrollY)||0))));restoringNavigation=false}
function closeDetail(){const nav=history.state?.[navigationKey];if(nav?.detailId&&Number(nav.depth)>0&&!historyBackPending){historyBackPending=true;history.back();return}state.detailId=null;replaceNavigation({detailId:null,detailTab:'overview'});if($('#detail').open)$('#detail').close()}
function closeDialog(dialog){if(dialog?.id==='detail')closeDetail();else dialog?.close()}
function setView(v,addHistory=true,preserveScroll=false){if(!validViews.includes(v))return;if(state.view!==v&&addHistory)pushNavigation({view:v,detailId:null,detailTab:'overview'});state.view=v;if(state.detailId&&!$('#detail').open)state.detailId=null;for(const [id,view] of [['discover-view','discover'],['catalog-view','catalog'],['collections-view','collections'],['list-view','list'],['platforms-view','platforms'],['community-view','community']])$('#'+id).hidden=v!==view;$$('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);if(v===b.dataset.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(!preserveScroll)window.scrollTo({top:0,behavior:motionPreference.matches?'auto':'smooth'});if(v==='catalog'){renderCatalog();loadCatalogIndex();}if(v==='discover'){renderRecommendations();renderHomeRankings();renderLiveShelf();}if(v==='collections')renderCuratedCollections();if(v==='list')renderLibrary();if(v==='platforms')renderPlatformPage();if(v==='community')window.SahneOpenCommunity?.(state.communityView,state.communityId);scheduleCinemaFrame()}
function setStatus(id,value){if(!byId.has(id))return;if(value==='remove'){delete saved[id]}else if(standardLists.some(([v])=>v===value)){const e=ensureEntry(id);e.status=value;if(value==='done'&&!e.date)e.date=new Date().toISOString().slice(0,10)}persist();renderAll();if(state.view==='list')renderLibrary();if(state.stagePool[state.stageIndex]===id)selectStage(state.stageIndex,false);if($('#detail').open&&state.detailId===id)detail(id,state.detailTab);}
function toggleFavorite(id){const e=ensureEntry(id);e.favorite=!e.favorite;persist();renderAll();if($('#detail').open)detailTab(state.detailTab);toast(e.favorite?'Favorilerine eklendi.':'Favorilerinden çıkarıldı.');}
function toggleCustomList(id,listId){const e=ensureEntry(id);e.lists=e.lists||[];e.lists.includes(listId)?e.lists=e.lists.filter(v=>v!==listId):e.lists.push(listId);persist();}
