function filteredForStage(){return SERIES.filter(s=>state.mood==='all'||s.mood===state.mood).map(s=>Number(s.id))}
function renderOrbit(center=true){const ids=state.stagePool;const orbit=$('#poster-orbit');orbit.innerHTML=ids.map((id,i)=>{const s=byId.get(id);return `<button class="orbit-poster ${i===state.stageIndex?'active':''}" data-stage-id="${id}" aria-label="${esc(s.name)}${i===state.stageIndex?', seçili':''}" aria-current="${i===state.stageIndex?'true':'false'}" tabindex="${i===state.stageIndex?'0':'-1'}"><img src="${s.image.original||s.image.medium}" alt="${esc(s.name)} afişi"><span>${String(i+1).padStart(2,'0')} / ${esc(s.name)}</span></button>`}).join('');if(center){const active=orbit.querySelector('.orbit-poster.active');active?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})}$('#stage-counter').textContent=`${String(state.stageIndex+1).padStart(2,'0')} / ${String(ids.length).padStart(2,'0')}`;$$('[data-stage-mood]').forEach(b=>{b.classList.toggle('active',b.dataset.stageMood===state.mood);b.setAttribute('aria-pressed',String(b.dataset.stageMood===state.mood))})}
function selectStage(i,scroll=true){if(!$('#poster-orbit'))return;if(!state.stagePool.length)return;state.stageIndex=(i+state.stagePool.length)%state.stagePool.length;const s=byId.get(state.stagePool[state.stageIndex]);$('#stage-number').textContent=String(state.stageIndex+1).padStart(2,'0');$('#stage-title').textContent=s.name;$('#stage-label').textContent=(s.label||'ÖZENLE SEÇİLDİ').replaceAll(' ',' / ');$('#stage-meta').textContent=`${s.year} · ${s.genres.slice(0,2).map(g=>esc(names[g]||g)).join(' / ')} · ~${s.runtime} dk`;$('#stage-description').textContent=s.description||s.reason;$('#stage-backdrop').style.backgroundImage=`url("${s.backdrop||DETAILS[String(s.id)]?.backdrops?.[0]||s.image.original}")`;$('#stage-detail').dataset.stageDetail=String(s.id);$('#stage-save').dataset.statusAction=String(s.id);$('#stage-save').textContent=getStatus(s.id)==='planned'?'✓ Sonra izle':'＋ Sonra izle';renderOrbit(scroll);}
