function renderCollections(){const html=collections.map(function(c,i){const shows=c.shows.map(function(id){return byId.get(id)}).filter(Boolean),lead=shows[0];if(!lead)return '';const backdrop=lead.backdrop||DETAILS[String(lead.id)]?.backdrops?.[0]||lead.image.original,stack=shows.slice(0,3).map(function(show,j){return '<img class="collection-poster poster-'+(j+1)+'" src="'+esc(show.image.original||show.image.medium)+'" alt="" loading="lazy">'}).join(''),label=c.key==='mind'?'ZİHNİN SINIRLARI':c.key==='warm'?'KÜÇÜK BİR MOLA':c.key==='dark'?'IŞIKLAR SÖNÜNCE':'SONUNA KADAR',titleList=shows.map(function(show){return esc(show.name)}).join('　·　');return '<button class="collection collection-'+c.key+'" data-collection="'+c.key+'"><div class="collection-art" aria-hidden="true"><img class="collection-backdrop" src="'+esc(backdrop)+'" alt="" loading="lazy"><div class="collection-stack">'+stack+'</div><span class="collection-art-index">SAHNE SEÇKİSİ / 0'+(i+1)+'</span></div><span class="tiny-label">0'+(i+1)+' / '+label+'</span><span class="collection-copy"><h3>'+esc(c.title)+'</h3><p>'+esc(c.sub)+'</p><span class="collection-list">'+titleList+'</span></span><span class="collection-arrow">'+iconSvg.arrow+'</span></button>'}).join('');$('#home-collections').innerHTML=html;$('#all-collections').innerHTML=html;}
