function renderGenreAtlas(){const html=genreAtlas.map(function(g,i){const shows=g.shows.map(function(id){return byId.get(id)}).filter(Boolean),lead=shows[0];if(!lead)return '';const art=shows.slice(0,2).map(function(show,j){return '<img class="atlas-poster atlas-poster-'+(j+1)+'" src="'+esc(show.image.original||show.image.medium)+'" alt="" loading="lazy">'}).join(''),backdrop=lead.backdrop||DETAILS[String(lead.id)]?.backdrops?.[0]||lead.image.original,count=browseRows().filter(function(show){return (!show.type||['Scripted','Animation'].includes(show.type))&&show.genres.includes(g.genre)}).length;return '<button class="atlas-card atlas-'+(i+1)+'" data-home-genre="'+esc(g.genre)+'" aria-label="'+esc(g.title)+' türündeki dizileri keşfet"><span class="atlas-art" aria-hidden="true"><img class="atlas-backdrop" src="'+esc(backdrop)+'" alt="" loading="lazy"><span class="atlas-poster-stack">'+art+'</span></span><span class="atlas-copy"><span class="atlas-eyebrow">'+esc(g.eyebrow)+'</span><strong>'+esc(g.title)+'</strong><span class="atlas-desc">'+esc(g.text)+'</span><span class="atlas-count">'+count+' dizi seçkide '+iconSvg.right+'</span></span><span class="atlas-index">0'+(i+1)+'</span></button>'}).join('');$('#genre-atlas').innerHTML=html;}
function renderHomePlatforms(){const entries=SERIES.flatMap(function(show){const country=showForCountry(show);return country?.state==='verified'?(country.offers||[]).slice(0,1).map(function(offer){return {s:show,o:offer}}):[]}).slice(0,8);$('#platform-region').textContent=countries[state.country];$('#platform-wall').innerHTML=entries.length?entries.map(function(entry,i){const show=entry.s,offer=entry.o,backdrop=show.backdrop||DETAILS[String(show.id)]?.backdrops?.[0]||show.image.original;return '<button class="platform-card" data-detail="'+show.id+'" data-detail-tab="watch" aria-label="'+esc(show.name)+' dizisinin '+esc(offer.name)+' izleme seçeneklerini gör"><span class="platform-art"><img src="'+esc(backdrop)+'" alt="" loading="lazy"><span class="platform-order">0'+(i+1)+'</span><span class="provider-chip">'+esc(offer.name)+'</span></span><span class="platform-card-copy"><strong>'+esc(show.name)+'</strong><span>'+esc(providerType(offer.type))+' · '+esc(show.year||'')+'</span></span></button>'}).join(''):'<div class="platform-empty"><strong>'+esc(countries[state.country])+' kataloğunda seçkiye ait doğrulanmış seçenek yok.</strong><span>Ülkeni üst menüden değiştir veya dizi ayrıntılarındaki izleme rehberini aç.</span></div>';}
function renderLibrary(){const owned=Object.entries(saved).map(([id,e])=>({s:byId.get(Number(id)),e})).filter(x=>x.s);const watched=owned.filter(x=>x.e.status==='done').length;const episodes=owned.reduce((n,x)=>n+(x.e.episodes||[]).length,0);const stats=[[owned.length,'DİZİ ARŞİVDE'],[watched,'TAMAMLANDI'],[episodes,'BÖLÜM İZLENDİ'],[owned.filter(x=>x.e.favorite).length,'FAVORİ']];$('#library-stats').innerHTML=stats.map(([n,l])=>`<div class="library-stat"><strong>${n}</strong><span>${l}</span></div>`).join('');$('#library-cover-posters').innerHTML=owned.slice(0,3).map(x=>`<img src="${x.s.image.medium}" alt="${esc(x.s.name)} afişi">`).join('');$('#list-count').textContent=owned.length;$('#custom-lists').innerHTML=customLists.map(l=>`<div class="custom-list-row"><button class="custom-list ${state.activeList===l.id?'active':''}" data-custom-filter="${esc(l.id)}"><strong>${esc(l.name)}</strong><span>${owned.filter(x=>(x.e.lists||[]).includes(l.id)).length} dizi · Aç</span></button><button class="custom-list-remove" data-delete-list="${esc(l.id)}" aria-label="${esc(l.name)} listesini sil" title="Listeyi sil">×</button></div>`).join('');const active=customLists.find(x=>x.id===state.activeList);$('#active-list-label').innerHTML=active?`<div><strong>${esc(active.name)}</strong>${active.description?`<p>${esc(active.description)}</p>`:''}</div><button class="text-button" data-custom-filter="">Tüm arşive dön</button>`:'';$$('[data-status]').forEach(b=>b.classList.toggle('active',b.dataset.status===state.status));let entries=owned;if(state.activeList)entries=entries.filter(x=>(x.e.lists||[]).includes(state.activeList));else if(state.status==='favorites')entries=entries.filter(x=>x.e.favorite);else if(state.status==='diary')entries=entries.filter(x=>x.e.review||x.e.date||x.e.stars);else if(state.status!=='all')entries=entries.filter(x=>x.e.status===state.status);const diary=state.status==='diary';$('#list-grid').hidden=diary;$('#diary-grid').hidden=!diary;$('#diary-grid').innerHTML=diary?[...entries].filter(x=>x.e.review||x.e.date||x.e.stars).sort((a,b)=>(b.e.date||'').localeCompare(a.e.date||'')).map(({s,e})=>`<article class="diary-entry"><button data-detail="${s.id}" aria-label="${esc(s.name)} ayrıntıları"><img src="${s.image.medium}" alt="${esc(s.name)} afişi"></button><div><span class="tiny-label">${e.date?fmtDate(e.date).toLocaleUpperCase('tr'):e.status?standardLists.find(x=>x[0]===e.status)?.[1]?.toLocaleUpperCase('tr'):'ARŞİV NOTU'}</span><button class="card-title" data-detail="${s.id}">${esc(s.name)}</button>${e.stars?`<span class="stars-preview">${'★'.repeat(Math.floor(e.stars))}${e.stars%1?'½':''} <span>${(Number(e.stars)*2).toFixed(1)} / 10</span></span>`:''}${e.review?`<p>${esc(e.review)}</p>`:''}</div><button class="soft-button" data-journal="${s.id}">Düzenle</button></article>`).join(''):'';$('#list-grid').innerHTML=entries.map(x=>card(x.s,true)).join('');$('#list-empty').hidden=!!entries.length;$('#list-pick').disabled=!owned.some(x=>x.e.status==='planned'||x.e.status==='watching');}
function renderContinue(){const inProgress=Object.entries(saved).filter(([,e])=>e.status==='watching').map(([id,e])=>({s:byId.get(Number(id)),e})).filter(x=>x.s).slice(0,3);$('#continue-section').hidden=!inProgress.length;$('#continue-grid').innerHTML=inProgress.map(({s,e})=>{const total=DETAILS[String(s.id)]?.episodes?.length||0,seen=(e.episodes||[]).length,pct=total?Math.round(seen/total*100):0;return `<article class="continue-card"><img src="${s.image.medium}" alt="${esc(s.name)} afişi"><div><button class="card-title" data-detail="${s.id}">${esc(s.name)}</button><p>${seen} / ${total||'?'} bölüm izlendi${e.season?` · ${e.season}. sezon`:''}</p><div class="progress"><span style="width:${pct}%"></span></div><button class="text-button" data-detail-tab="episodes" data-detail="${s.id}">Kaldığım yerden</button></div></article>`}).join('');}
function renderAll(){renderRecommendations();if(state.view==='catalog')renderCatalog();if(state.view==='list')renderLibrary();renderContinue();if(state.view==='discover'){renderHomeRankings();renderLiveShelf();}if(state.view==='platforms')renderPlatformPage();$('#list-count').textContent=Object.keys(saved).length;refreshHomeArchiveButtons();}
function renderWatch(s){return window.SahneWatch.render(s,state.country)}
function safeText(s){const div=document.createElement('div');div.innerHTML=s||'';return div.textContent||div.innerText||''}
function hydrateTvmazeDetails(id){if(DETAILS[String(id)]||!dynamicShows.has(id)||detailRequests.has(id))return;const request=fetch(`https://api.tvmaze.com/shows/${id}?embed[]=episodes&embed[]=cast`,{headers:{Accept:'application/json'}}).then(response=>{if(!response.ok)throw new Error(`TVmaze yanıtı: ${response.status}`);return response.json()}).then(raw=>{const show=rememberTvmazeShow(raw),embedded=raw._embedded||{},episodes=Array.isArray(embedded.episodes)?embedded.episodes.map(ep=>({id:Number(ep.id),season:Number(ep.season)||0,number:Number(ep.number)||0,name:String(ep.name||'Bölüm'),airdate:ep.airdate||'',runtime:Number(ep.runtime)||0})):[],seasons=[...new Set(episodes.map(ep=>ep.season))].sort((a,b)=>a-b);DETAILS[String(id)]={status:raw.status||'',seasons:seasons.map(number=>({number})),episodes,cast:Array.isArray(embedded.cast)?embedded.cast.map(item=>({name:item.person?.name||'Oyuncu',character:item.character?.name||'Karakter',image:item.person?.image?.medium||null})):[],backdrops:[]};saveDynamicCatalog();if(ratings[id]||saved[id]?.stars||saved[id]?.favorite)renderAll();if(state.detailId===id&&$('#detail').open){$('#detail-content').innerHTML=detailShell(show);detailTab(state.detailTab);window.SahneCommunity?.renderSeries(id,$('#series-community'))}}).catch(error=>{if(error.name!=='AbortError'&&state.detailId===id&&$('#detail').open)toast('Ek dizi ayrıntıları şu an yüklenemedi. TVmaze bağlantısını sonra yeniden dene.')}).finally(()=>detailRequests.delete(id));detailRequests.set(id,request)}
function detail(id,tab='overview'){const s=byId.get(Number(id));if(!s)return;state.detailId=Number(id);$('#detail-content').innerHTML=detailShell(s);if(!$('#detail').open)$('#detail').showModal();detailTab(tab);window.SahneCommunity?.renderSeries(Number(id),$('#series-community'));hydrateTvmazeDetails(Number(id))}
function openDetail(id,tab='overview'){const s=byId.get(Number(id));if(!s)return;const n=Number(id);if($('#detail').open&&state.detailId===n){detail(n,tab);return}pushNavigation({view:state.view,detailId:n,detailTab:tab});detail(n,tab)}
function detailShell(s){const d=DETAILS[String(s.id)]||{},e=saved[s.id]||{},img=s.backdrop||d.backdrops?.[0]||s.image.original;return `<header class="detail-hero" style="background-image:url('${img}')"><img src="${s.image.original}" alt="${esc(s.name)} afişi"><div><span class="tiny-label">${esc(s.label||'SAHNE SEÇKİSİ')}</span><h2 id="detail-title">${esc(s.name)}</h2><p class="detail-meta">${s.year||'—'} · ${s.genres.map(g=>esc(names[g]||g)).join(' / ')||'Tür bilgisi yok'} · ${s.runtime?`~${s.runtime} dk`:'Süre bilgisi yok'}${d.seasons?.length?` · ${d.seasons.length} sezon`:''}<br>${esc((d.status||s.status)==='Ended'?'Tamamlandı':(d.status||s.status)==='Running'?'Devam ediyor':d.status||s.status||'')}</p></div></header><div class="detail-quick"><button class="primary" data-status-action="${s.id}" data-status-value="planned">${e.status==='planned'?'✓ Sonra izlenecek':'＋ Sonra izle'}</button><button class="soft-button" data-favorite="${s.id}" aria-pressed="${!!e.favorite}">${e.favorite?iconSvg.heartFill+' Favorilerde':iconSvg.heart+' Favorilere ekle'}</button>${ratingButtons(s)}</div><nav class="detail-tabs" aria-label="Dizi ayrıntıları"><button data-detail-tab="overview">Hikâye & kadro</button><button data-detail-tab="watch">Nerede izlenir?</button><button data-detail-tab="episodes">Sezonlar & bölümler</button><button data-detail-tab="journal">Günlüğüm</button></nav><div class="detail-panel" id="detail-panel"></div><section id="series-community" class="detail-panel"></section>`}
function detailTab(tab){const s=byId.get(state.detailId);if(!s)return;state.detailTab=tab;replaceNavigation({detailId:state.detailId,detailTab:tab});$$('.detail-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.detailTab===tab);b.setAttribute('aria-current',b.dataset.detailTab===tab?'page':'false')});const panel=$('#detail-panel');if(tab==='watch'){const keepCountryFocus=panel.contains(document.activeElement)&&document.activeElement.matches('[data-watch-country]');panel.innerHTML=renderWatch(s);if(keepCountryFocus)panel.querySelector('[data-watch-country]')?.focus({preventScroll:true});window.SahneWatch.load(s,state.country);return}if(tab==='journal'){panel.innerHTML=journalForm(s);setJournalStars(saved[s.id]?.stars||0);return}if(tab==='episodes'){panel.innerHTML=episodesPanel(s);return}const d=DETAILS[String(s.id)]||{},e=saved[s.id]||{},seasonInfo=d.seasons||[],cast=d.cast||[];panel.innerHTML=`<div class="overview-grid"><div><h3>Bir hikâyenin başlangıcı</h3><p class="synopsis">${esc(s.description||safeText(s.summary)||'Dizi özeti yükleniyor. Ayrıntılar için TVmaze kaydını da açabilirsin.')}</p><p class="reason"><strong>Sana neden uyabilir?</strong><br>${esc(s.reason||'')}</p>${s.officialSite?`<div class="detail-links"><a class="secondary" href="${s.officialSite}" target="_blank" rel="noopener">Dizinin resmî sayfası</a>${d.trailer?`<a class="soft-button" href="${d.trailer}" target="_blank" rel="noopener">Fragmanı aç</a>`:''}</div>`:''}</div><dl class="fact-grid"><div><dt>YAYIN DURUMU</dt><dd>${esc((d.status||s.status)==='Ended'?'Tamamlandı':(d.status||s.status)==='Running'?'Devam ediyor':d.status||s.status||'Bilgi yok')}</dd></div><div><dt>SEZON</dt><dd>${seasonInfo.length||'—'}</dd></div><div><dt>BÖLÜM SÜRESİ</dt><dd>${s.runtime?`~${s.runtime} dakika`:'Bilgi yok'}</dd></div><div><dt>TVMAZE PUANI</dt><dd>${s.rating?`${s.rating} / 10`:'—'}</dd></div><div><dt>İZLENEN BÖLÜM</dt><dd>${(e.episodes||[]).length}${d.episodes?.length?` / ${d.episodes.length}`:''}</dd></div><div><dt>GÜNLÜK PUANIN</dt><dd>${e.stars?`${(e.stars*2).toFixed(1)} / 10`:'Henüz puanlamadın'}</dd></div></dl></div>${cast.length?`<section class="subsection"><h3>Hikâyeye can verenler</h3><div class="cast-grid">${cast.map(c=>`<div class="cast-card">${c.image?`<img src="${c.image}" alt="${esc(c.name)}">`:`<div class="cast-fallback">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>`}<strong>${esc(c.name)}</strong><span>${esc(c.character)}</span></div>`).join('')}</div></section>`:''}<section class="subsection"><h3>Günlüğüne ekle</h3><p class="muted">Bu diziye puan ver, bir not bırak ya da izleme durumunu kaydet.</p><button class="primary" style="margin-top:15px" data-detail-tab="journal">Günlüğümde yer aç</button> <a class="detail-source" href="${s.source}" target="_blank" rel="noopener">Dizi verisi: TVmaze</a></section>`;}
function journalForm(s){const e=saved[s.id]||{};const d=DETAILS[String(s.id)]||{},watched=new Set(e.episodes||[]);return `<form class="journal-form" data-journal-form="${s.id}"><label>Arşiv durumu<select name="status">${[['none','Arşivden kaldır'],...standardLists].map(([v,t])=>`<option value="${v}" ${(e.status||'none')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>İzlediğin tarih<input type="date" name="date" value="${e.date||''}"></label><label class="full">Kişisel notun<textarea name="review" rows="5" maxlength="1500" placeholder="Nesi sende kaldı? Bir sahne, bir replik, hissettirdiği…">${esc(e.review||'')}</textarea></label><label>Senin puanın / 10<select name="rating" aria-label="On üzerinden puanın"><option value="0">Henüz puanlamadım</option>${Array.from({length:19},(_,i)=>1+i/2).map(n=>`<option value="${n}" ${e.stars*2===n?'selected':''}>${n.toFixed(1)} / 10</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" name="favorite" ${e.favorite?'checked':''}> Favorilerime ekle</label>${customLists.length?`<fieldset class="full"><legend>Kişisel seçkilerin</legend><div class="journal-list-checks">${customLists.map(l=>`<label class="check-label"><input type="checkbox" name="lists" value="${esc(l.id)}" ${(e.lists||[]).includes(l.id)?'checked':''}> ${esc(l.name)}</label>`).join('')}</div></fieldset>`:`<div class="muted">Arşivindeki dizileri kişisel seçkilere ayırmak için yeni liste oluştur.</div>`}<div class="full form-actions"><p>${window.SahneCommunity?.currentUser?'Arşivin hesabına kaydedilir.':'Hesabına giriş yaparak arşivini cihazlar arasında taşı.'}<br>Bu günlük notu sana özeldir; yorumlar aşağıda paylaşılır.</p><button class="primary" type="submit">Günlüğü kaydet</button></div></form>`}
function setJournalStars(n){$$('[data-star]').forEach(b=>{const on=Number(b.dataset.star)<=n;b.classList.toggle('on',on);b.textContent=on?'★':'☆';b.setAttribute('aria-pressed',String(Number(b.dataset.star)===n))})}
function episodesPanel(s){const d=DETAILS[String(s.id)]||{},episodes=d.episodes||[],savedEpisodes=new Set(saved[s.id]?.episodes||[]);if(!episodes.length)return `<h3>Bölüm listesi henüz hazır değil.</h3><p class="muted">İzleme durumunu arşivinden güncelleyebilirsin.</p>`;const groups=new Map();episodes.forEach(ep=>{if(!groups.has(ep.season))groups.set(ep.season,[]);groups.get(ep.season).push(ep)});const all=savedEpisodes.size,latestSeason=episodes.filter(ep=>ep.airdate&&ep.airdate<=localDate()).reduce((last,ep)=>Math.max(last,ep.season),0)||[...groups.keys()].at(-1);return `<div class="episode-top"><div><h3>Her bölüm bir sahne daha.</h3><p>${all} / ${episodes.length} bölüm izlendi.</p></div><button class="secondary" data-episode-all="${s.id}">${all===episodes.length?'Tümünü geri al':'Tümünü izlendi işaretle'}</button></div>${[...groups.entries()].map(([season,eps],i)=>`<details class="season-group" ${season===latestSeason?'open':''}><summary><strong>${season?`${season}. sezon`:'Özel bölümler'}</strong><span>${eps.filter(ep=>savedEpisodes.has(ep.id)).length} / ${eps.length} izlendi⌄</span></summary>${eps.map(ep=>`<label class="episode"><input type="checkbox" data-episode="${s.id}" value="${ep.id}" ${savedEpisodes.has(ep.id)?'checked':''}><span><strong>${String(ep.number).padStart(2,'0')}. ${esc(ep.name)}</strong><small>${ep.airdate?fmtDate(ep.airdate):'Yayın tarihi eklenmemiş'}</small></span>${ep.runtime?`<time>${ep.runtime} dk</time>`:''}</label>`).join('')}</details>`).join('')}`;}
function applyEpisode(id,epId,checked){const e=ensureEntry(id);e.episodes=e.episodes||[];e.episodes=checked?[...new Set([...e.episodes,epId])]:e.episodes.filter(x=>x!==epId);if(checked&&e.status==='planned')e.status='watching';persist();if($('#detail').open)detailTab('episodes');renderLibrary();renderContinue();}
function renderDiaryMenu(){/* Diary forms are scoped to each series; top-level entry is in the archive tabs. */}
function openQuiz(){quizStep(1);$('#quiz').showModal()}
let quizMood='all';function quizStep(n){$('#quiz-content').innerHTML=n===1?`<span class="tiny-label">BUGÜNÜN MODU / 01</span><h2 id="quiz-title">Hangi dünyaya gidelim?</h2><div class="quiz-options"><button class="quiz-option" data-answer="mind">Aklımı kurcalasın</button><button class="quiz-option" data-answer="warm">İçimi biraz ısıtsın</button><button class="quiz-option" data-answer="dark">Karanlık, merak uyandırsın</button><button class="quiz-option" data-answer="intense">Temposu yüksek olsun</button></div>`:`<span class="tiny-label">BUGÜNÜN MODU / 02</span><h2 id="quiz-title">Bir bölüme ne kadar vaktin var?</h2><div class="quiz-options"><button class="quiz-option" data-time="35">Hızlı bir mola · 35 dakikaya kadar</button><button class="quiz-option" data-time="65">Bir saate yakın</button><button class="quiz-option" data-time="999">Zamanım var, iyi hikâye olsun</button></div><button id="quiz-back" class="text-button">← Geri</button>`}
function quizResults(time){const pool=TasteEngine.recommend(recommendationCandidates().filter(s=>s.mood===quizMood),tasteCatalog(),ratings,saved);const match=pool.filter(s=>s.runtime<=time);const shows=match.length?match:pool;$('#quiz-content').innerHTML=`<span class="tiny-label">SENİN İÇİN BİR SAHNE</span><h2 id="quiz-title">Belki de bu akşamın.</h2><p class="muted">${match.length?'Ruh hâlin ve bölüm sürene göre seçildi.':'Seçtiğin ruh hâlinde biraz daha uzun seçeneklere bakalım.'}</p>${shows.slice(0,3).map(s=>`<div class="quiz-result"><img src="${s.image.medium}" alt="${esc(s.name)} afişi"><div><h3>${esc(s.name)}</h3><p>~${s.runtime} dk · ${esc(recommendationReason(s))}</p></div><button data-detail="${s.id}" aria-label="${esc(s.name)} ayrıntıları">→</button></div>`).join('')}${!shows.length?'<p class="muted">Bu temadaki dizileri zaten değerlendirdin veya arşivine ekledin. Başka bir ruh hâli seç.</p>':''}<button id="quiz-again" class="soft-button">Yeniden seç</button>`}
function journalSubmit(form){const id=Number(form.dataset.journalForm),fd=new FormData(form);if(!byId.has(id))return;const status=fd.get('status'),review=String(fd.get('review')||'').trim(),date=String(fd.get('date')||''),stars=Number(fd.get('rating')||0)/2,favorite=fd.get('favorite')==='on',lists=fd.getAll('lists');const e={...(saved[id]||{})};if(status==='none')delete e.status;else if(standardLists.some(([x])=>x===status))e.status=status;if(review)e.review=review;else delete e.review;if(date)e.date=date;else delete e.date;if(stars>0)e.stars=Math.min(5,stars);else delete e.stars;e.favorite=favorite;if(lists.length)e.lists=lists;else delete e.lists;const hasData=!!(e.status||e.review||e.date||e.stars||e.favorite||e.lists?.length||e.episodes?.length);if(hasData)saved[id]=e;else delete saved[id];persist();renderAll();if($('#detail').open)detail(id,'journal');toast('Günlüğün güncellendi.');}
function exportLibrary(){const blob=new Blob([JSON.stringify({name:'Sahne arşivi',exportedAt:new Date().toISOString(),entries:saved,lists:customLists,ratings,catalog:[...dynamicShows.values()]},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sahne-arsiv-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Arşiv kopyan indirildi.');}
function renderCustomInModal(){const form=$('#detail-content form[data-journal-form]');if(form)detailTab('journal')}
function createList(fd){const name=String(fd.get('name')||'').trim();if(!name)return;if(customLists.length>=30){toast('Daha fazla kişisel liste oluşturamazsın.');return}const l={id:`list-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name,description:String(fd.get('description')||'').trim()};customLists.push(l);state.activeList=l.id;state.status='all';persist();$('#list-dialog').close();renderLibrary();toast('Yeni seçkin hazır.');}
function deleteCustomList(id){const list=customLists.find(x=>x.id===id);if(!list)return;customLists=customLists.filter(x=>x.id!==id);for(const [key,entry] of Object.entries(saved)){entry.lists=(entry.lists||[]).filter(x=>x!==id);if(!entry.lists.length)delete entry.lists;if(!Object.keys(entry).length)delete saved[key]}if(state.activeList===id)state.activeList=null;persist();renderLibrary();toast('Kişisel seçki silindi. Dizi arşivin korundu.');}
function onDocClick(e){const b=e.target.closest('button,a');if(!b)return;if(b.dataset.platform){e.preventDefault();openPlatform(b.dataset.platform);return}if(b.dataset.heroStory!==undefined){setHeroStory(Number(b.dataset.heroStory));return}if(b.dataset.storyChapter!==undefined){goToStoryChapter(Number(b.dataset.storyChapter));return}if(b.dataset.homeSave){const id=Number(b.dataset.homeSave);setStatus(id,getStatus(id)==='planned'?'remove':'planned');return}if(b.id==='platform-reset'){state.platformQuery='';state.platformGenre='all';$('#platform-search').value='';$('#platform-genre').value='all';renderPlatformCatalog();return}if(b.id==='platform-region-link'){window.scrollTo({top:0,behavior:'smooth'});$('#country').focus();try{$('#country').showPicker?.()}catch{}return}if(state.dragged&&b.matches('[data-stage-id]')){state.dragged=false;e.preventDefault();return}if(b.classList.contains('close')){closeDialog(b.closest('dialog'));return}if(b.dataset.view){e.preventDefault();setView(b.dataset.view);return}if(b.dataset.scrollTrack){const track=$('#'+b.dataset.scrollTrack);track?.scrollBy({left:Number(b.dataset.dir||1)*Math.max(280,track.clientWidth*.72),behavior:'smooth'});return}if(b.dataset.rate){rate(Number(b.dataset.rate),b.dataset.value);return}if(b.dataset.stageMood!==undefined){setStageMood(b.dataset.stageMood);return}if(b.dataset.stageId){const idx=state.stagePool.indexOf(Number(b.dataset.stageId));if(idx>=0)selectStage(idx);return}if(b.id==='stage-prev'){selectStage(state.stageIndex-1);return}if(b.id==='stage-next'){selectStage(state.stageIndex+1);return}if(b.id==='stage-detail'){openDetail(Number(b.dataset.stageDetail||state.stagePool[state.stageIndex]));return}if(b.id==='stage-save'){const id=Number(b.dataset.statusAction||state.stagePool[state.stageIndex]);setStatus(id,getStatus(id)==='planned'?'remove':'planned');return}if(b.dataset.stageDetail){openDetail(Number(b.dataset.stageDetail));return}if(b.dataset.detail){openDetail(Number(b.dataset.detail),b.dataset.detailTab||'overview');return}if(b.dataset.detailTab){if(b.dataset.detail)openDetail(Number(b.dataset.detail),b.dataset.detailTab);else detailTab(b.dataset.detailTab);return}if(b.dataset.statusAction){setStatus(Number(b.dataset.statusAction),b.dataset.statusValue);return}if(b.dataset.favorite){const tab=state.detailTab;toggleFavorite(Number(b.dataset.favorite));if($('#detail').open)detailTab(tab);return}if(b.dataset.detailTab==='journal'){detailTab('journal');return}if(b.dataset.genre!==undefined){state.genre=b.dataset.genre;renderCatalog();renderRecommendations();return}if(b.dataset.homeGenre){openCatalogShelf('popular');state.genre=b.dataset.homeGenre;renderCatalog();return}if(b.dataset.collection){openCatalogCollection(b.dataset.collection);return}if(b.dataset.status){state.status=b.dataset.status;state.activeList=null;renderLibrary();return}if(b.dataset.deleteList){deleteCustomList(b.dataset.deleteList);return}if(b.dataset.customFilter!==undefined){state.activeList=b.dataset.customFilter||null;renderLibrary();return}if(b.dataset.journal){openDetail(Number(b.dataset.journal),'journal');return}if(b.dataset.star){const input=$('.star-value');const n=Number(b.dataset.star),current=Number(input.value);input.value=current===n?'0':String(n);setJournalStars(current===n?0:n);return}if(b.dataset.quizDetail){$('#quiz').close();openDetail(Number(b.dataset.quizDetail));return}if(b.dataset.answer){quizMood=b.dataset.answer;quizStep(2);return}if(b.dataset.time){quizResults(Number(b.dataset.time));return}if(b.dataset.episodeAll){const id=Number(b.dataset.episodeAll),eps=DETAILS[String(id)]?.episodes||[],e=ensureEntry(id);if(eps.length&&(e.episodes||[]).length<eps.length){e.episodes=eps.map(x=>x.id);if(e.status==='planned')e.status='watching'}else e.episodes=[];if(e.episodes.length&&e.status==='planned')e.status='watching';persist();detailTab('episodes');renderAll();return}if(b.id==='quiz-open'){openQuiz();return}if(b.id==='quiz-back'||b.id==='quiz-again'){quizStep(1);return}if(b.id==='surprise'){const pool=TasteEngine.recommend(recommendationCandidates(),tasteCatalog(),ratings,saved);if(pool.length)openDetail(pool[Math.floor(Math.random()*Math.min(4,pool.length))].id);else toast('Bu seçkide yeni öneri kalmadı. Başka bir atmosfer dene.');return}if(b.id==='search-open'){setView('catalog');$('#search').focus();return}if(b.id==='create-list'){state.activeList=null;$('#list-name').value='';$('#list-description').value='';$('#list-dialog').showModal();$('#list-name').focus();return}if(b.id==='export-library'){exportLibrary();return}if(b.id==='list-pick'){const picks=Object.keys(saved).map(x=>Number(x)).filter(id=>['planned','watching'].includes(saved[id]?.status)&&ratings[id]!=='dislike');if(picks.length)openDetail(picks[Math.floor(Math.random()*picks.length)]);else toast('Sonra izle listende seçebileceğin dizi yok.');return}if(b.id==='reset'){resetBrowseFilters();return}}
document.addEventListener('click',onDocClick);
document.addEventListener('change',e=>{const t=e.target;if(t.id==='country')setCountry(t.value);else if('watchCountry'in t.dataset)setCountry(t.value);else if(t.id==='available-only')renderCatalog();else if(t.id==='sort'){state.sort=t.value;renderCatalog()}else if(t.dataset.setStatus)setStatus(Number(t.dataset.setStatus),t.value);else if(t.dataset.episode)applyEpisode(Number(t.dataset.episode),Number(t.value),t.checked)});
document.addEventListener('submit',e=>{if(e.target.matches('[data-journal-form]')){e.preventDefault();journalSubmit(e.target)}if(e.target.id==='list-form'){e.preventDefault();createList(new FormData(e.target))}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;queueCatalogSearch()});$('#country').value=localStorage.getItem('sahne-country-v1')||'TR';state.country=$('#country').value;
$('#poster-orbit')?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();selectStage(state.stageIndex-1)}if(e.key==='ArrowRight'){e.preventDefault();selectStage(state.stageIndex+1)}if(e.key==='Enter'){e.preventDefault();openDetail(state.stagePool[state.stageIndex])}});
let dragX=0,dragScroll=0;$('#poster-orbit')?.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;dragX=e.clientX;dragScroll=e.currentTarget.scrollLeft;e.currentTarget.classList.add('dragging')});$('#poster-orbit')?.addEventListener('pointermove',e=>{if(!e.currentTarget.classList.contains('dragging')||!e.buttons)return;if(Math.abs(e.clientX-dragX)>7)state.dragged=true;e.currentTarget.scrollLeft=dragScroll-(e.clientX-dragX)});for(const n of ['pointerup','pointercancel','pointerleave'])$('#poster-orbit')?.addEventListener(n,e=>{if(e.currentTarget.classList.contains('dragging'))e.currentTarget.classList.remove('dragging');setTimeout(()=>state.dragged=false,0)});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)closeDialog(d)}));$('#detail').addEventListener('close',()=>{if(restoringNavigation||historyBackPending)return;const nav=history.state?.[navigationKey];if(nav?.detailId)closeDetail();else state.detailId=null});window.addEventListener('popstate',restoreNavigation);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();setView('catalog');$('#search').focus()}});
function renderInitial(){initializeCatalogExperience();renderGenreAtlas();renderHomePlatforms();renderHomeExperience();renderAll();}
window.SahneWatch.install({countries,archive:(id,country)=>WATCH_DATA[String(id)]?.countries?.[country],onCountryChange:setCountry,onLoaded:record=>{const id=String(record.show.id);WATCH_DATA[id]=WATCH_DATA[id]||{countries:{}};WATCH_DATA[id].countries[record.country]=record;if(state.country===record.country)renderHomePlatforms();}});
const initialNavigation=initializeNavigation();renderInitial();setView(initialNavigation.view,false,true);if(initialNavigation.detailId)resolveNavigationDetail(initialNavigation);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'search_series',description:'Search all show titles in the TVmaze catalog; returns the closest title matches.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:2}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(typeof input?.query!=='string'||input.query.trim().length<2)throw Error('Enter at least two letters to search TVmaze');const query=input.query.trim(),results=await queryTvmaze(query);state.query=query;state.collection=null;state.mood='all';state.genre='all';searchMatches=results;$('#search').value=query;setView('catalog');searchStatus(`TVmaze’den en yakın ${results.length} başlık eşleşmesi bulundu.`);renderCatalog();saveDynamicCatalog();return {source:'TVmaze',results:results.map(s=>({id:s.id,name:s.name,year:s.year,genres:s.genres}))}}});register({name:'set_watchlist_status',description:'Set or remove a series from the device-local archive.',inputSchema:{type:'object',properties:{id:{type:'integer'},status:{enum:['planned','watching','done','paused','dropped','remove']}},required:['id','status'],additionalProperties:false},annotations:{readOnlyHint:false},execute(x){if(!byId.has(x?.id)||!['planned','watching','done','paused','dropped','remove'].includes(x?.status))throw Error('Invalid series id or archive status');setStatus(x.id,x.status);setView('list');return {id:x.id,status:getStatus(x.id)||'removed'}}});register({name:'rate_series',description:'Give a series a like, strong like, or dislike. Feedback updates local personalized recommendations.',inputSchema:{type:'object',properties:{id:{type:'integer'},rating:{enum:['dislike','like','love','clear']}},required:['id','rating'],additionalProperties:false},annotations:{readOnlyHint:false},execute(x){if(!byId.has(x?.id)||!['dislike','like','love','clear'].includes(x?.rating))throw Error('Invalid series id or rating');if(x.rating==='clear')delete ratings[x.id];else ratings[x.id]=x.rating;saveRatings();renderAll();return {id:x.id,rating:ratings[x.id]||'cleared',nextSuggestions:TasteEngine.recommend(recommendationCandidates(),tasteCatalog(),ratings,saved).slice(0,3).map(s=>s.name)}}});register({name:'get_watch_options',description:'Read country-specific streaming, rental and purchase options inside Sahne with direct provider links.',inputSchema:{type:'object',properties:{id:{type:'integer'},country:{enum:['TR','US','GB','DE']}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:true},async execute(x){if(!byId.has(x?.id))throw Error('Unknown series id');const c=x.country||state.country;if(!countries[c])throw Error('Unsupported country');const w=await window.SahneWatch.lookup(x.id,c);return {series:byId.get(x.id).name,country:c,status:w.state,checkedAt:w.checkedAt,source:w.source,offers:w.offers}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
